/* Send plans restore the production TX data/timing path; no board claims. */
#include "sim/send_plan.h"
#include "sim/sim_api.h"
#include "sim/env_sim.h"
#include "sim/tx_sequence.h"
#include "app/app.h"
#include "app/ui/core/ui_sm.h"
#include "services/core/app_evt.h"
#include "services/core/app_timer.h"
#include "services/power/power_sm.h"
#include "services/can_core/chan_sm.h"
#include "services/frame_ring/frame_ring.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"FAIL %d: %s\n",__LINE__,#x);exit(1);}}while(0)
static ring_reader_t reader;
static can_frame_t seen[256];static unsigned seen_count;
static void observe(void){const can_frame_t *f;while((f=ring_peek(&reader))!=NULL){if(f->flags&CANF_TX){CHECK(seen_count<256);seen[seen_count++]=*f;}ring_advance(&reader);}}
static void step(unsigned ms){app_tick(ms);txseq_tick();sp_tick();env_tick(ms);app_tick(0);observe();}
static void run(unsigned ms){for(unsigned i=0;i<ms;i++)step(1);}
static void post(ev_type_t type,int ch,int a,int b){CHECK(evt_post4(type,(uint8_t)ch,SRC_UI,a,b));app_tick(0);}
static void normal(int ch){post(EV_REQ_CH_MODE,ch,CAN_MODE_NORMAL,2);CHECK(chan_can_tx(ch));}
static void boot(void){sim_reset();sp_init();sim_key(KEY_POWER,1);for(int i=0;i<170;i++)sim_tick(10);sim_key(KEY_POWER,0);for(int i=0;i<5;i++)sim_tick(10);CHECK(power_running());env_cmd("bus_fps",0,0);env_cmd("bus_fps",1,0);txseq_init();seen_count=0;ring_reader_attach(&reader,false);}
static send_plan_t fixture(uint32_t mask){send_plan_t plan;CHECK(sp_capture(mask,&plan)==0);for(int ch=0;ch<2;ch++)if(mask&(1u<<ch)){for(int i=0;i<4;i++)plan.channels[ch].entries[i].enabled=0;plan.channels[ch].id_gap_ms=7;send_plan_entry_t *a=&plan.channels[ch].entries[0],*b=&plan.channels[ch].entries[1];a->enabled=1;a->repeat_count=3;a->frame_gap_ms=10;a->cycle_ms=50;b->enabled=1;b->repeat_count=2;b->frame_gap_ms=5;b->cycle_ms=20;}CHECK(sp_validate(&plan)==0);return plan;}
static sp_file_t install(const send_plan_t *plan,const char *name){sp_file_t f;memset(&f,0,sizeof f);snprintf(f.name,sizeof f.name,"%s",name);f.plan=*plan;CHECK(sp_catalog_replace(&f,1)==0);CHECK(sp_catalog_get(0,&f));CHECK(f.token!=0);return f;}
static void validate_and_catalogue(void){boot();send_plan_t p=fixture(1),bad=p;CHECK(sizeof p==1036);bad.channels[0].entries[0].flags=CANF_ERR;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);bad=p;bad.channels[0].entries[0].length=9;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);bad=p;bad.channels[0].entries[0].repeat_count=0;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);bad=p;bad.channels[0].entries[0].cycle_ms=20;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);bad=p;bad.channels[0].entries[0].dynamic[4]=99;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);bad=p;bad.channels[0].entries[0].data[63]=1;CHECK(sp_validate(&bad)==SP_ERR_FORMAT);
 sp_file_t old=install(&p,"road.canplan.json");CHECK(sp_catalog_replace(&old,1)==0);sp_file_t same;CHECK(sp_catalog_get(0,&same)&&same.token==old.token);sp_file_t invalid=old;invalid.plan=bad;CHECK(sp_catalog_replace(&invalid,1)==SP_ERR_FORMAT);CHECK(sp_catalog_get(0,&same)&&same.token==old.token);invalid=old;strcpy(invalid.name,"../road.canplan.json");CHECK(sp_catalog_replace(&invalid,1)==SP_ERR_FORMAT);CHECK(sp_catalog_count()==1);p.channels[0].entries[0].data[0]^=1;sp_file_t changed=install(&p,"road.canplan.json");CHECK(changed.token!=old.token);CHECK(sp_load(0,old.token)==SP_ERR_CHANGED);
}
static void immutable_io_and_names(void){boot();send_plan_t p=fixture(2),copy=p;char name[48],next[48];sp_default_name(2,name,sizeof name);sp_default_name(2,next,sizeof next);CHECK(strcmp(name,next)!=0&&strstr(name,"CAN2")&&strstr(name,".canplan.json"));CHECK(sp_request_save("../bad.canplan.json",&p)==SP_ERR_NAME);CHECK(sp_request_save("CON.canplan.json",&p)==SP_ERR_NAME);CHECK(sp_request_save(name,&p)==0);p.channels[1].entries[0].id=0x333;sp_io_request_t request;CHECK(sp_io_peek(&request));CHECK(request.kind==SP_IO_SAVE&&!memcmp(&request.plan,&copy,sizeof copy));CHECK(sp_request_refresh()==SP_ERR_BUSY);CHECK(sp_io_complete(request.id+1,0,"wrong")==SP_ERR_CHANGED&&sp_io_peek(&request));CHECK(sp_io_complete(request.id,SP_ERR_IO,"disk failure")==SP_ERR_IO);CHECK(!sp_io_peek(&request)&&sp_state()->last_error==SP_ERR_IO);CHECK(sp_request_refresh()==0);CHECK(sp_io_peek(&request)&&request.kind==SP_IO_REFRESH);CHECK(sp_io_complete(request.id,0,"refreshed")==0);CHECK(!sp_state()->io_pending);}
static void save_running_and_isolated_load(void){boot();normal(0);normal(1);txseq_entry_config_t cfg[4];memcpy(cfg,txseq_get(1)->entries,sizeof cfg);for(int i=0;i<4;i++)cfg[i].enabled=i==0;CHECK(txseq_configure(1,cfg,10,txseq_get(1)->revision)==0);CHECK(txseq_start(1,txseq_get(1)->revision)==0);run(12);send_plan_t p=fixture(1);sp_file_t f=install(&p,"can1.canplan.json");uint32_t other_revision=tx_get()->e[1][0].revision,other_sent=txseq_get(1)->sent;CHECK(sp_load(0,f.token)==0);CHECK(txseq_get(1)->state==TXSEQ_RUNNING&&tx_get()->e[1][0].revision==other_revision&&txseq_get(1)->sent==other_sent);CHECK(sp_start()==0);run(12);uint32_t before=txseq_get(0)->sent;send_plan_t snapshot;CHECK(sp_capture(1,&snapshot)==0);CHECK(txseq_get(0)->state==TXSEQ_RUNNING&&txseq_get(0)->sent==before);CHECK(sp_request_save("running.canplan.json",&snapshot)==0);sp_stop();CHECK(txseq_get(0)->state==TXSEQ_IDLE&&txseq_get(1)->state==TXSEQ_RUNNING);run(110);CHECK(txseq_get(1)->sent>other_sent);txseq_stop(1);}
static void atomic_busy_and_changed(void){boot();normal(0);normal(1);send_plan_t p=fixture(3);sp_file_t f=install(&p,"both.canplan.json");can_frame_t old=tx_get()->e[0][0].f;uint32_t revision=tx_get()->e[0][0].revision;CHECK(txseq_start(1,txseq_get(1)->revision)==0);CHECK(sp_load(0,f.token)==SP_ERR_BUSY);CHECK(!memcmp(&old,&tx_get()->e[0][0].f,sizeof old)&&tx_get()->e[0][0].revision==revision);txseq_stop(1);CHECK(sp_load(0,f.token)==0&&!tx_any_active());uint8_t data[8]={1};CHECK(tx_entry_update(1,0,0x222,0,8,data,10)==TX_OK);CHECK(sp_start()==SP_ERR_CHANGED&&!tx_any_active());}
static void aggregate_confirmation_and_cancel(void){boot();send_plan_t p=fixture(3);sp_file_t f=install(&p,"confirm.canplan.json");CHECK(sp_load(0,f.token)==0);CHECK(sp_start_once()==SP_WAIT_CONFIRM);app_tick(0);CHECK(ui_dialog_open()&&sp_state()->state==SP_CONFIRMING);CHECK(txseq_get(0)->sent==0&&txseq_get(1)->sent==0);uint32_t request=sp_state()->request;/* Test callback directly only after dismissing the display queue. */sim_touch(2,1);CHECK(!ui_dialog_open()&&sp_state()->state==SP_LOADED);CHECK(!tx_any_active()&&seen_count==0);CHECK(sp_answer(request,true)==SP_ERR_CHANGED);CHECK(sp_start_once()==SP_WAIT_CONFIRM);app_tick(0);sim_touch(2,0);app_tick(0);sp_tick();run(150);CHECK(!ui_dialog_open());CHECK(txseq_get(0)->rounds==1&&txseq_get(1)->rounds==1);CHECK(txseq_get(0)->sent==5&&txseq_get(1)->sent==5);CHECK(txseq_get(0)->state==TXSEQ_IDLE&&txseq_get(1)->state==TXSEQ_IDLE);CHECK(sp_state()->state==SP_LOADED);uint32_t a=txseq_get(0)->sent,b=txseq_get(1)->sent;run(200);CHECK(txseq_get(0)->sent==a&&txseq_get(1)->sent==b);}
static void exact_single_round_and_dynamic_replay(void){boot();normal(0);send_plan_t p=fixture(1);p.channels[0].entries[0].dynamic[3]=7;sp_file_t f=install(&p,"deterministic.canplan.json");CHECK(sp_load(0,f.token)==0);CHECK(sp_start_once()==0);run(130);CHECK(seen_count==5&&txseq_get(0)->rounds==1&&txseq_get(0)->stop_reason==TXSEQ_STOP_COMPLETE);can_frame_t first[5];memcpy(first,seen,sizeof first);static const unsigned times[]={0,10,20,57,62};for(unsigned i=0;i<5;i++)CHECK(seen[i].ts_us-first[0].ts_us==(uint64_t)times[i]*1000);CHECK((seen[0].data[6]&15)==7&&(seen[1].data[6]&15)==8&&(seen[2].data[6]&15)==9);CHECK(seen[0].data[7]==crc8_j1850(seen[0].data,7));unsigned before=seen_count;run(100);CHECK(seen_count==before);
 seen_count=0;CHECK(sp_load(0,f.token)==0);CHECK(sp_start_once()==0);run(130);CHECK(seen_count==5);for(unsigned i=0;i<5;i++){CHECK(seen[i].id==first[i].id&&seen[i].len==first[i].len);CHECK(!memcmp(seen[i].data,first[i].data,seen[i].len));CHECK(seen[i].ts_us-seen[0].ts_us==first[i].ts_us-first[0].ts_us);}seen_count=0;CHECK(sp_start_once()==0);run(130);CHECK(seen_count==5&&!memcmp(seen[0].data,first[0].data,8));}
static void single_round_different_channel_durations(void){
 boot();normal(0);normal(1);send_plan_t p=fixture(3);p.channels[1].entries[0].repeat_count=1;p.channels[1].entries[1].enabled=0;sp_file_t f=install(&p,"different.canplan.json");CHECK(sp_load(0,f.token)==0);CHECK(sp_start_once()==0);run(10);CHECK(txseq_get(1)->sent==1&&txseq_get(1)->rounds==1&&txseq_get(1)->state==TXSEQ_IDLE);CHECK(txseq_get(0)->state==TXSEQ_RUNNING&&sp_state()->state==SP_RUNNING);run(130);CHECK(txseq_get(0)->sent==5&&txseq_get(0)->rounds==1&&sp_state()->state==SP_LOADED);CHECK(txseq_get(1)->sent==1);
}
static void active_plan_cannot_be_orphaned_by_disjoint_load(void){
 boot();normal(0);normal(1);sp_file_t list[2];memset(list,0,sizeof list);strcpy(list[0].name,"first.canplan.json");list[0].plan=fixture(1);strcpy(list[1].name,"second.canplan.json");list[1].plan=fixture(2);CHECK(sp_catalog_replace(list,2)==0);CHECK(sp_catalog_get(0,&list[0])&&sp_catalog_get(1,&list[1]));CHECK(sp_load(0,list[0].token)==0&&sp_start()==0);run(3);CHECK(sp_load(1,list[1].token)==SP_ERR_BUSY);CHECK(sp_state()->loaded_mask==1&&txseq_get(0)->state==TXSEQ_RUNNING&&txseq_get(1)->state==TXSEQ_IDLE);sp_stop();run(2);CHECK(txseq_get(0)->state==TXSEQ_IDLE);CHECK(sp_load(1,list[1].token)==0);
}
static void project_catalogue_identity_and_validation(void){
 boot();send_plan_t p=fixture(1);sp_file_t f=install(&p,"project.canplan.json");CHECK(sizeof f==1136);CHECK(!strcmp(f.project,"未分组"));uint32_t before=f.token;strcpy(f.project,"动力项目");CHECK(sp_catalog_replace(&f,1)==0);CHECK(sp_catalog_get(0,&f)&&f.token!=before);before=f.token;CHECK(sp_catalog_replace(&f,1)==0);CHECK(sp_catalog_get(0,&f)&&f.token==before);CHECK(sp_load(0,f.token)==0);
 sp_file_t bad=f;strcpy(bad.project,"A/B");CHECK(sp_catalog_replace(&bad,1)==SP_ERR_FORMAT);CHECK(sp_catalog_get(0,&bad)&&bad.token==before);bad=f;memset(bad.project,'x',sizeof bad.project);CHECK(sp_catalog_replace(&bad,1)==SP_ERR_FORMAT);bad=f;strcpy(bad.project,"A\177B");CHECK(sp_catalog_replace(&bad,1)==SP_ERR_FORMAT);bad=f;strcpy(bad.project," A");CHECK(sp_catalog_replace(&bad,1)==SP_ERR_FORMAT);
 strcpy(f.project,"车身项目");CHECK(sp_catalog_replace(&f,1)==0);normal(0);CHECK(sp_start()==SP_ERR_CHANGED);CHECK(!tx_any_active());
}
static void global_stop_cancels_arming_and_running_plan(void){
 boot();send_plan_t p=fixture(3);sp_file_t f=install(&p,"stop.canplan.json");CHECK(sp_load(0,f.token)==0&&sp_start()==SP_WAIT_CONFIRM);app_tick(0);sim_touch(2,0);CHECK(sp_state()->state==SP_ARMING);post(EV_REQ_TX_STOP_ALL,0,0,0);CHECK(sp_state()->state==SP_LOADED);run(50);CHECK(!tx_any_active()&&seen_count==0);CHECK(sp_start()==0);run(3);uint32_t first=txseq_get(0)->sent,second=txseq_get(1)->sent;CHECK(first==1&&second==1);post(EV_REQ_TX_STOP_ALL,0,0,0);CHECK(sp_state()->state==SP_LOADED);run(150);CHECK(txseq_get(0)->sent==first&&txseq_get(1)->sent==second&&!tx_any_active());
}
int main(void){validate_and_catalogue();immutable_io_and_names();save_running_and_isolated_load();atomic_busy_and_changed();aggregate_confirmation_and_cancel();exact_single_round_and_dynamic_replay();single_round_different_channel_durations();active_plan_cannot_be_orphaned_by_disjoint_load();project_catalogue_identity_and_validation();global_stop_cancels_arming_and_running_plan();printf("Send-plan snapshot / restore / exact rounds: %u checks passed\n",checks);return 0;}
